Proof.
  intros a s Hs Ha. pose proof (u64_range a) as Ra.
  pose proof (shiftr_lt_pow2 (bv_unsigned a) s 47 Hs ltac:(lia)) as B.
  rewrite <- (u_v_srli a s Hs) in B |- *. apply u_v_or47; lia.
Qed.

